SELECT classification_id
FROM classification
WHERE merge_key = #{mergeKey}

mapper.update:
UPDATE patent_classification pc SET deleted = true, updated_at = now() FROM ( VALUES
(#{p.companyId}::bigint, #{p.childId}::bigint)
) AS scope(company_id, patent_id) WHERE pc.company_id = scope.company_id AND pc.patent_id = scope.patent_id AND pc.deleted = false AND pc.sync_id != #{syncId}::uuid
